const icons={arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',chevron:'m8 5 7 7-7 7',down:'m5 9 7 7 7-7',close:'m6 6 12 12M18 6 6 18',check:'m4 12 5 5L20 6',plus:'M12 4v16M4 12h16',minus:'M4 12h16',book:'M12 5c-3-2-7-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-3-1-7-1-10 1v15M5 8h4m6 0h4',pen:'m4 17 12-12 4 4L8 21H3l1-4Zm10-10 4 4',castle:'M4 20V7H2V3h4v3h4V3h4v3h4V3h4v4h-2v13H4Zm5 0v-6h6v6',target:'M12 2v4m0 12v4M2 12h4m12 0h4M20 12a8 8 0 1 1-16 0 8 8 0 0 1 16 0Zm-5 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',settings:'m9 3-1 3-3 1-2 4 2 2v3l4 3 3-1 3 1 4-3v-3l2-2-2-4-3-1-1-3H9Zm7 9a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',help:'M9 8c0-4 7-4 7 0 0 3-4 3-4 6m0 4h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',exit:'M9 3H3v18h6m6-14 5 5-5 5M8 12h12',map:'m3 4 6 2 6-3 6 2v16l-6-2-6 3-6-2V4Zm6 2v16m6-19v16',play:'m8 4 12 8-12 8V4Z',pause:'M7 4v16M17 4v16',fast:'m3 5 9 7-9 7V5Zm9 0 9 7-9 7V5Z',drop:'M12 2S4 11 4 15a8 8 0 0 0 16 0c0-4-8-13-8-13Z',heart:'M12 21 3 12C-3 3 8-2 12 6c4-8 15-3 9 6l-9 9Z',shield:'m12 2 9 4v7c0 5-9 9-9 9s-9-4-9-9V6l9-4Z',undo:'M4 9h10c9 0 9 12 0 12M4 9l5-5M4 9l5 5',redo:'M20 9H10C1 9 1 21 10 21m10-12-5-5m5 5-5 5',grid:'M3 3h18v18H3V3Zm6 0v18m6-18v18M3 9h18M3 15h18',move:'M12 2v20M2 12h20M8 6l4-4 4 4M8 18l4 4 4-4M6 8l-4 4 4 4m12-8 4 4-4 4',square:'M4 4h16v16H4V4Z',circle:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',line:'M4 20 20 4M6 20a2 2 0 1 1-4 0 2 2 0 0 1 4 0ZM22 4a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',erase:'m3 14 10-11 8 8-10 10H8l-5-7Zm5-6 8 8m-5 5h11',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',zoom:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Zm-1 6 6 6',fit:'M3 9V3h6m6 0h6v6M3 15v6h6m6 0h6v-6M8 8h8v8H8V8Z',save:'M3 3h15l3 3v15H3V3Zm4 0v6h10V3M7 21v-8h10v8',lock:'M6 10V7a6 6 0 0 1 12 0v3M4 10h16v12H4V10Zm8 5v3',info:'M12 11v7m0-12h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',flag:'M4 22V3c5-5 10 5 16 0v10c-6 5-11-5-16 0',bolt:'m13 2-9 12h7l-1 8 10-13h-7V2Z',refresh:'M20 8a9 9 0 1 0 1 8M20 8h-6m6 0V2',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',layers:'m12 2 10 6-10 6L2 8l10-6ZM2 12l10 6 10-6M2 17l10 6 10-6',search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Zm-1 6 6 6',copy:'M8 8h13v13H8V8ZM16 4V2H2v14h2',trophy:'M7 3h10v9c0 6-10 6-10 0V3Zm0 2H3v5c0 3 4 4 4 4m10-9h4v5c0 3-4 4-4 4m-5 2v6m-5 0h10',wall:'M2 4h20v16H2V4Zm0 8h20M8 4v8m8 0v8',mirror:'M12 2v20M8 6l-6 6 6 6V6Zm8 0 6 6-6 6V6Z',magnet:'M5 3v10a7 7 0 0 0 14 0V3h-4v10a3 3 0 0 1-6 0V3H5Zm0 5h4m6 0h4'};
const I=(id,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[id]||icons.target}"/></svg>`;
const B=(label,icon='',route='',style='secondary')=>`<button class="btn ${style}" ${!label&&icon?`aria-label="${({back:'Назад',close:'Закрыть'})[icon]||icon}"`: ''} ${route?`data-go="${route}"`:'data-act="feedback"'}>${icon?I(icon):''}${label}</button>`;
const IB=(icon,label,act='feedback')=>`<button class="btn icon-only secondary" title="${label}" aria-label="${label}" data-act="${act}">${I(icon)}</button>`;
const S=(id,x=0,y=0,k=1,rot=0)=>`<g transform="translate(${x} ${y}) rotate(${rot}) scale(${k})">${ART[id]||''}</g>`;
const svg=(content,box='-1 -1 2 2')=>`<svg class="art" viewBox="${box}" aria-hidden="true">${content}</svg>`;
const A=(id)=>svg(S(id),id.startsWith('object.castle')?'-.85 -.85 1.7 1.7':id.startsWith('chassis.')?'-.6 -.4 1.2 .8':'-.6 -.6 1.2 1.2');
const tower=(kind=0)=>svg(S(['chassis.standard','chassis.heavy','chassis.precision','chassis.battery'][kind%4],0,.12,1.3)+S(['weapon.gun','weapon.mortar','weapon.piercer','weapon.ricochet'][kind%4],kind===3?-.3:0,-.02,.95,0)+(kind===3?S('weapon.gun',.26,-.02,.95,0):''),'-.95 -1.15 1.9 2');
const metric=(n,t)=>`<div class="metric"><strong>${n}</strong><span>${t}</span></div>`;
const tag=(t,c='')=>`<span class="tag ${c}">${t}</span>`;
const row=(k,v,c='')=>`<div class="data-row"><span class="muted">${k}</span><strong class="${c}">${v}</strong></div>`;
const cur=()=>`<span class="currency"><span class="coin">✦</span> 240 <small class="muted">золота</small></span>`;
const titlebar=(title,back='home',extra='')=>`<header class="topbar"><div class="top-title">${B('','back',back,'icon-only secondary')}<h1>${title}</h1></div><div class="top-right">${cur()}${extra||B('Мастерская','pen','foundation')}</div></header>`;
const foot=(left,right,note='')=>`<footer class="pagefooter"><div class="row">${left}</div>${note?`<span class="hint">${note}</span>`:''}<div class="row">${right}</div></footer>`;
const head=(h,p,extra='')=>`<div class="content-head"><div><h2>${h}</h2>${p?`<p>${p}</p>`:''}</div>${extra}</div>`;
const keys=(k)=>`<kbd>${k}</kbd>`;
const note=(text,type='')=>`<div class="alert ${type}">${I(type==='error'?'info':'check')}<div>${text}</div></div>`;
function field(mode='planning'){
 let active=['battle','tower','pause','upgrades','victory','defeat','leave'].includes(mode);
 let g=`<defs><pattern id="fieldgrid" width="42" height="42" patternUnits="userSpaceOnUse"><path d="M42 0H0V42" fill="none" stroke="#d5e1f2" stroke-width=".8"/></pattern></defs><rect width="1000" height="650" fill="#f8fafc"/><rect width="1000" height="650" fill="url(#fieldgrid)"/><path d="M4 215C180 210 200 335 490 330M760 4c-130 190-150 220-260 326M996 490c-180 80-340-30-496-160" fill="none" stroke="#b8c9df" stroke-width="2" stroke-dasharray="8 9"/><path d="M4 215C180 210 200 335 490 330M760 4c-130 190-150 220-260 326M996 490c-180 80-340-30-496-160" fill="none" stroke="none"/>`;
 g+=S('object.castle',510,330,42);g+=S('object.well.red',210,480,25)+S('object.well.blue',800,450,25)+S('object.well.green',550,120,25);
 const trees=[[85,120],[110,150],[870,120],[900,150],[750,550],[130,560]];
 trees.forEach(([x,y],i)=>{g+=`<g opacity=".35">${S(i%2?'terrain.pine':'terrain.rock',x,y,45)}</g>`});
 if(active||mode==='planning'){[[360,285,0],[430,430,3],[635,285,1],[610,450,2]].forEach(([x,y,k])=>{g+=`<circle cx="${x}" cy="${y}" r="74" fill="#3158dc05" stroke="#3158dc25" stroke-dasharray="4 6"/>${S('chassis.standard',x,y,42)}${S(['weapon.gun','weapon.mortar','weapon.piercer','weapon.fan'][k],x,y-2,36,-65)}`});for(let i=0;i<5;i++)g+=S('object.wall.0',330,330+i*19,18);}
 if(active){[[78,216],[115,226],[150,245],[182,250],[208,278],[243,283],[270,304],[292,291],[730,80],[714,115],[690,145],[685,185],[665,204],[940,505],[900,502],[870,508],[846,490]].forEach(([x,y],i)=>{g+=S(i%3===0?'enemy.runner.outlined.idle':'enemy.doodle.outlined.idle',x,y,30);});g+=`<path d="M352 285 270 304M628 284 665 204M430 428 292 291" stroke="#3158dc" stroke-width="2.5"/><circle cx="270" cy="304" r="15" fill="none" stroke="#ca4051" stroke-width="2"/><circle cx="665" cy="204" r="15" fill="none" stroke="#3158dc" stroke-width="2"/>`;}
 g+=`<g fill="#c54c60"><path d="m10 206 14 9-14 9z"/><path d="m750 10 10 15 10-15z"/><path d="m990 482-15 10 15 10z"/></g>`;
 return svg(g,'0 0 1000 650');
}
function heroArt(){return svg(`<defs><pattern id="heroGrid" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M35 0H0V35" fill="none" stroke="#d4e2f4" stroke-width=".8"/></pattern></defs><g transform="rotate(-4 400 350)"><rect x="35" y="55" width="725" height="590" rx="22" fill="white" stroke="#d8e4f2"/><rect x="35" y="55" width="725" height="590" rx="22" fill="url(#heroGrid)"/><path d="M85 55v590" stroke="#efc8cf" stroke-width="1"/>${S('object.castle',480,290,71)}${S('chassis.battery',300,425,75)}${S('weapon.gun',276,405,67,-48)}${S('weapon.fan',326,405,60,-30)}${S('chassis.precision',580,480,65)}${S('weapon.mortar',580,466,65,-35)}<path d="M295 385 184 220M324 386 222 196M581 428Q460 125 267 185" fill="none" stroke="#3158dc" stroke-width="2.5" stroke-dasharray="8 7"/>${S('enemy.doodle.outlined.idle',175,223,53)}${S('enemy.gnawer.outlined.idle',240,172,53)}${S('enemy.runner.outlined.idle',340,135,49)}<path d="M153 491c-40 75 35 120 151 66" stroke="#3158dc" fill="none" stroke-width="3"/><path d="m288 547 19 9-12 16" stroke="#3158dc" fill="none" stroke-width="3"/></g><g transform="translate(688 426) rotate(25)"><rect x="-12" y="-180" width="24" height="215" rx="5" fill="#3158dc"/><path d="m-12 35 12 36 12-36" fill="#d6b796"/><path d="m-4 59 4 12 4-12" fill="#233953"/><path d="M-4-175V25" stroke="#7b9afa" stroke-width="3"/></g>`,'0 0 800 720')}
function home(){return `<div class="screen home-screen"><header class="topbar"><div class="logo">${I('pen')} Держи линию</div><div class="top-right">${cur()}${IB('settings','Настройки','settings')}</div></header><section class="home-main"><div class="home-copy"><div class="kicker"><span class="badge-dot"></span> Оборона, которую ты нарисовал</div><h1>Твоя линия.<br>Твои правила.</h1><p>Собери башню, нарисуй её характер и защити страницу от каракулей.</p>${B('Начать игру','arrow','map','primary')}<div class="row" style="margin-top:18px">${I('map')}<span class="small muted">Первый рубеж · 8 волн</span></div></div><div class="home-art"><div class="scene-grid"></div>${heroArt()}<span class="paper-note">Всё начинается с одного штриха</span></div></section><footer class="home-footer"><nav class="home-links">${B('Мастерская','pen','foundation','ghost')}${B('Настройки','settings','settings','ghost')}${B('Как играть','help','help','ghost')}</nav>${B('Выйти','exit','','ghost')}</footer></div>`}
function map(){return `<div class="screen">${titlebar('Карта','home',B('Альбом','book','album'))}<div class="pagecontent"><div class="page-grid"><section class="map-panel scene-grid">${field('map')}<div class="map-title">${tag('Первый рубеж','blue')}</div><div class="map-legend"><span>◆ Замок</span><span>◯ Чернильницы</span><span>↘ Направления атаки</span><span>96 × 64 клетки</span></div></section><aside class="sidebar"><div class="card stack grow"><div class="row between">${tag('Миссия 01','blue')}${tag('Доступна','good')}</div><div class="mission-art">${A('object.castle')}</div><h2>Первый рубеж</h2><p>Защити замок от восьми волн. Перекрой проходы и удержи оборону до последнего штриха.</p><div class="metrics">${metric('8','волн')}${metric('720','штрихов на старте')}</div><div class="rule"></div><h3>На этой странице</h3><p class="small">Открытые подходы, скалы и лес. Три чернильницы дают цвет, но требуют защиты.</p><div class="push">${B('Подготовить оборону','arrow','preparation','primary wide')}</div></div></aside></div></div>${foot(B('В меню','back','home','ghost'),B('Как играть','help','help','ghost'),'Выбирай чертежи перед началом миссии')}</div>`}
const blueprints=[['Страж','Быстрый одиночный огонь',51,0],['Капля','Площадной удар',64,1],['Игла','Пробивает ряд целей',65,2],['Двойной штрих','Два ствола · общая подача',108,3]];
function preparation(){return `<div class="screen">${titlebar('Подготовка к миссии','map',B('Альбом','book','album'))}<div class="pagecontent">${head('Четыре чертежа. Одна оборона.','Выбери башни, которые возьмёшь на страницу. Стены, шипы, смола и ремонт доступны в бою.',tag('Первый рубеж · 8 волн','blue'))}<div class="grid4">${blueprints.map((b,i)=>`<article class="card loadout-card"><div class="slot-number"><span>Чертёж ${i+1}</span>${keys(i+1)}</div><div class="artbox">${tower(b[3])}</div><h3>${b[0]}</h3><p class="small">${b[1]}</p><div class="row between"><span class="blue small">${b[2]} штр.</span>${B('Заменить','refresh','album','small secondary')}</div></article>`).join('')}</div><div class="loadout-bottom"><div class="card stack"><h3>Начальный материал</h3><div class="material-choice">${['Карандаш','Ручка','Фломастер'].map((m,i)=>`<button class="chip ${i===0?'selected':''}" data-select="material">${I('pen')}${m}</button>`).join('')}</div><p class="small">Материал можно сменить во время боя.</p></div><div class="card soft row"><div class="grow"><h3>Готов к первому штриху?</h3><p class="small" style="margin-top:8px">Постройки расходуют штрихи. Золото открывает новые детали в мастерской.</p></div><div class="metrics">${metric('720','штрихов')}${metric('250','HP замка')}</div></div></div></div>${foot(B('К карте','back','map','ghost')+B('В мастерскую','pen','foundation'),B('Начать защиту','play','planning','primary'))}</div>`}
function steps(current){return `<aside class="steps">${['Основа','Оружие','Рисунок','Проверка'].map((s,i)=>`<button class="step ${current===i?'active':i<current?'done':''}" data-go="${['foundation','weapons','drawing','review'][i]}"><span class="step-number">${i<current?'✓':i+1}</span>${s}</button>`).join('')}<div class="step-preview">${tower(0)}<p>Страж · твой чертёж</p></div></aside>`}
function wizard(main,side,step=0,next='weapons',label='К оружию',alert=''){return `<div class="screen">${titlebar('Мастерская','preparation',B('Альбом','book','album'))}<div class="wizard-grid">${steps(step)}<section class="wizard-main">${main}</section><aside class="sidebar">${side}</aside></div>${foot(B('Назад','back',['preparation','foundation','weapons','drawing'][step],'ghost')+B('К подготовке','map','preparation','secondary'),alert?B(label,'arrow','','primary'):B(label,'arrow',next,'primary'),alert)}</div>`}
function standardStats(){return `<div class="card soft stack"><h2>Твоя башня</h2><div class="artbox" style="height:145px">${tower(0)}</div><div class="stats-list">${row('Нагрузка','4 / 10')}${row('Цена постройки','51 штр.')}${row('Прочность','87,6 HP')}${row('Креплений','2')}</div><p class="small">Один корпус — общая прочность и подача для всех стволов.</p></div><div class="card stack"><div class="row">${I('info')}<h3>Без списания золота</h3></div><p class="small">Сборка, рисование и испытания бесплатны. Золото нужно только для открытия деталей.</p></div>`}
function foundation(){let names=['Обычная','Тяжёлая','Специализированная','Батарея'];let desc=['Гибкое начало для двух стволов','Больше прочности и общей нагрузки','Один ствол, больше улучшений','Три ствола на общей подаче'];return wizard(`${head('Выбери основу','С неё начинается вместимость и характер будущей башни.')}<div class="grid2">${names.map((n,i)=>`<button class="card option-card clickable ${i===0?'selected':''}" data-select="chassis"><div class="row between"><h3>${n}</h3>${i===0?tag('Выбрана','blue'):i===3?tag('Открыта','good'):''}</div><div class="artbox">${A(['chassis.standard','chassis.heavy','chassis.precision','chassis.battery'][i])}</div><p class="small">${desc[i]}</p><div class="row between small"><span>${[2,2,1,3][i]} крепл.</span><span>Нагрузка ${[10,14,16,22][i]}</span></div></button>`).join('')}</div>`,standardStats());}
const weaponNames=['Пулемёт','Пробой','Мортира','Веер','Рикошет','Скрепкострел','Промокашка'];const weaponIds=['gun','piercer','mortar','fan','ricochet','stapler','blotter'];
function weapons(){return wizard(`${head('Чем будет стрелять башня?','Назначь оружие каждому креплению. Свободное крепление можно оставить пустым.')}<div class="row mount-slots"><button class="chip selected" data-select="mount">Ствол 1 · Пулемёт</button><button class="chip" data-select="mount">Ствол 2 · Пусто</button></div><div class="weapon-grid">${weaponNames.map((n,i)=>`<button class="card weapon-card clickable ${i===0?'selected':''}" data-select="weapon"><div class="artbox">${A('weapon.'+weaponIds[i])}</div><h3>${n}</h3><p>${['Одна цель','Сквозной выстрел','Площадь','Несколько целей','Цепочка','Замедление','Очистка пятен'][i]}</p></button>`).join('')}<button class="card weapon-card clickable" data-select="weapon"><div class="artbox">${I('minus')}</div><h3>Пустое крепление</h3><p>Без нагрузки</p></button></div><div class="rule"></div><div class="row between"><h3>Дополнения</h3>${tag('Отдельные слоты')}</div><div class="row">${B('Броня','shield','armor')}${B('Подача','layers','','secondary')}${B('Наведение','target','','secondary')}${B('Направляющая','line','','secondary')}</div><div class="row"><span class="small muted">Особые настройки:</span>${B('Мортира','','mortar','small ghost')}${B('Веер','','fan','small ghost')}</div>`,standardStats(),1,'drawing','К рисунку');}
function drawCanvas(invalid=false,details=false){let main=`<line x1="250" y1="35" x2="250" y2="440" stroke="#91aacc" stroke-dasharray="5 6"/><line x1="70" y1="280" x2="430" y2="280" stroke="#91aacc" stroke-dasharray="5 6"/><path d="m165 240 28-28h115l28 28v95l-30 30H194l-29-29Z" fill="#3158dc04" stroke="#a7b9d7" stroke-width="2"/>`;if(!invalid)main+=`<path d="M234 280 236 115Q250 95 264 115L266 280Z" fill="#3158dc09" stroke="#254774" stroke-width="2.3"/><path d="m250 270 0-40m-7 8 7-8 7 8" stroke="#3158dc" fill="none" stroke-width="1.5"/>`;if(details)main+=`<path d="M280 280h28M280 105h28M298 105v175" stroke="#3158dc" fill="none"/><text x="312" y="195" fill="#3158dc" font-size="14">Длина</text><path d="M234 300v20m32-20v20m-32-8h32" stroke="#26765c"/><text x="228" y="343" fill="#26765c" font-size="13">Ширина</text>`;return svg(main,'0 0 500 440')}
function drawingSide(details=false,invalid=false){return `<div class="card soft stack"><h2>Твой рисунок</h2><div><div class="row between small"><span>Чернила</span><strong>49,4 / 65</strong></div><div class="progress" style="margin-top:10px"><i style="width:76%"></i></div></div><div class="stats-list"><div class="stat-pair"><span>Цена постройки</span><strong>51 <small>штр.</small></strong></div><div class="stat-pair"><span>Прочность</span><strong>87,6 <small>HP</small></strong></div><div class="stat-pair"><span>Нагрузка</span><strong>4 <small>/ 10</small></strong></div></div><div class="rule"></div><h3>Ствол 1 · пулемёт</h3><div class="grid2">${metric('12,6','урон')}${metric('8,6','дальность')}</div>${B(details?'Скрыть расчёты':'Подробности и изменения','down',details?'drawing':'details','small ghost')}${details?`<div class="data-row"><span>Длина ствола</span><strong class="blue">0,8 → 1,2</strong></div><div class="data-row"><span>Дальность</span><strong class="green">8 → 8,6</strong></div><div class="data-row"><span>Цена</span><strong>40 → 51</strong></div>`:`<p class="small ${invalid?'red':'green'}">${I(invalid?'info':'check')} ${invalid?'Ствол 1 не закончен':'Рисунок готов к проверке'}</p>`}</div><div class="card stack"><div class="row between"><h3>Мини-проба</h3>${tag('Бесплатно')}</div><div class="mini-trial scene-grid">${svg(`<path d="M28 55h180" stroke="#9ab0d7" stroke-dasharray="5 6"/><circle cx="28" cy="55" r="6" fill="none" stroke="#3158dc" stroke-width="2"/>${S('enemy.doodle.outlined.idle',206,55,23)}<path class="shot" d="M35 55h160" stroke="#3158dc" stroke-width="2"/>`,'0 0 240 110')}</div><div class="row between small"><span>Дистанция: 6 клеток</span>${IB('plus','Увеличить дистанцию')}</div>${invalid?'<button class="btn wide" disabled>Нужен рисунок ствола</button>':B('Выстрелить','target','','primary wide')}<p class="small muted">Одна мишень · без брони</p></div>`}
function drawing(kind='drawing'){let invalid=kind==='invalid';let details=kind==='details';return wizard(`${head('Нарисуй свою башню','Ствол растёт от крестика вверх — туда полетит выстрел.',B('Заготовки','book','stencils','small secondary'))}<div class="segmented"><button class="chip" data-select="layer">${I('castle')}Корпус</button><button class="chip selected" data-select="layer">${I('pen')}Ствол 1</button><button class="chip" data-select="layer">${I('layers')}Декор</button></div>${invalid?note('Ствол 1 ещё пустой. Добавь контур, чтобы башня могла стрелять.','error'):''}<div class="drawing-layout"><div class="drawtools">${[['pen','Карандаш'],['line','Прямая'],['square','Прямоугольник'],['circle','Эллипс'],['erase','Ластик'],['move','Перемещение']].map(([id,t],i)=>`<button class="btn icon-only ${i===0?'selected':'secondary'}" data-select="drawtool" aria-label="${t}" title="${t}">${I(id)}</button>`).join('')}</div><div class="drawcanvas scene-grid">${drawCanvas(invalid,details)}<span class="canvas-label">${invalid?'Пустой слой · ствол 1':'Рабочая геометрия'} · сетка 1:1</span></div></div><div class="row between toolbar"><div class="row">${IB('undo','Отменить')}${IB('redo','Повторить')}${IB('mirror','Зеркальность')}${IB('trash','Очистить','invalid')}</div><div class="row">${IB('grid','Сетка')}${IB('magnet','Привязка')}${B('100%','zoom','','small ghost')}${IB('fit','Вписать')}<button class="btn small ghost" data-toggle="size-controls">Размер</button></div></div><div id="size-controls" class="size-controls" hidden><label class="field-label">Ширина <input type="range" min="50" max="150" value="100" aria-label="Ширина рисунка"></label><label class="field-label">Высота <input type="range" min="50" max="150" value="100" aria-label="Высота рисунка"></label></div>`,drawingSide(details,invalid),2,invalid?'drawing':'review',invalid?'Нарисовать ствол':'К проверке');}
function review(){return wizard(`${head('Сохрани свой первый рубеж','Форма готова. Дай башне имя и проверь её на общем полигоне.')}<div class="review-art scene-grid">${tower(0)}</div><label class="field-label">Название чертежа<input type="text" maxlength="40" value="Страж" aria-label="Название чертежа"></label>${note('Корпус и ствол завершены. Нагрузка и расход чернил в пределах основы.','good')}<div class="row">${B('Испытать на полигоне','target','trial')}${B('Создать вариант','copy','album','ghost')}</div>`,`<div class="card soft stack"><h2>Страж</h2><p>Обычная основа<br>Один пулемёт</p>${row('Цена постройки','51 штр.')}${row('Прочность','87,6 HP')}${row('Урон','12,6')}${row('Дальность','8,6 кл.')}${row('Интервал','0,53 с')}${row('Нагрузка','4 / 10')}<div class="rule"></div><p class="small">Сохранение добавит чертёж в альбом. Чтобы взять башню в бой, назначь её в один из четырёх слотов.</p></div>`,3,'album','Сохранить в альбом');}

function album(empty=false){return `<div class="screen">${titlebar('Альбом чертежей','review',B('Новая башня','plus','foundation','primary'))}<div class="pagecontent"><div class="album-layout"><section class="stack">${head(empty?'Первая страница ждёт тебя':'Твоя коллекция штрихов',empty?'Сохрани башню в мастерской, чтобы взять её в бой.':'Каждый чертёж — отдельная идея. В боевом наборе четыре места.')}<div class="row between"><label class="grow"><input type="search" placeholder="Найти чертёж…" aria-label="Найти чертёж" data-filter="blueprints"></label>${tag(empty?'0 чертежей':'6 чертежей')}</div>${empty?`<div class="card grow center" style="min-height:380px;gap:16px"><div class="empty-figure">${I('book')}</div><h2>Начни с одной линии</h2><p>Выбери основу, добавь оружие<br>и нарисуй свою первую башню.</p>${B('Создать башню','pen','foundation','primary')}</div>`:`<div class="album-cards">${[...blueprints,['Страж · вариант','Длинный ствол',57,0],['Капля · вариант','Широкий отпечаток',71,1]].map((b,i)=>`<button class="card clickable ${i===0?'selected':''}" data-select="blueprint" data-name="${b[0]}"><div class="row between"><span class="small muted">${i<4?'В наборе · '+(i+1):'Вариант'}</span>${i===0?I('check'):I('book')}</div><div class="artbox">${tower(b[3])}</div><h3>${b[0]}</h3><p>${b[1]}</p><div class="row between small" style="margin-top:14px"><span>${b[2]} штр.</span><span>${i===3?'2 ствола':'1 ствол'}</span></div></button>`).join('')}</div><div class="row">${B('Редактировать','pen','drawing')}${B('Создать вариант','copy','','secondary')}${B('Удалить','trash','','ghost')}</div>`}</section><aside class="sidebar"><div class="card stack"><h2>Взять в бой</h2><p class="small">Назначь выбранный чертёж в слот.</p>${blueprints.map((b,i)=>`<button class="album-slot btn" data-act="${empty?'feedback':'assign'}" ${empty?'disabled':''}>${empty?I('plus'):tower(b[3])}<span class="grow" style="text-align:left"><small>Слот ${i+1}</small>${empty?'Пусто':b[0]}</span>${keys(i+1)}</button>`).join('')}<p class="small muted">Назначение не удаляет другие страницы из альбома.</p></div>${empty?'':`<div class="card soft stack"><h3>Страж</h3>${row('Прочность','87,6 HP')}${row('Цена','51 штр.')}${row('Нагрузка','4 / 10')}<p class="small">Обычная основа · пулемёт</p></div>`}</aside></div></div>${foot(B('Вернуться к черновику','back','drawing','ghost'),B('К подготовке','arrow','preparation','primary'))}</div>`}
function trial(){return `<div class="screen">${titlebar('Полигон','review',B('Вернуться к чертежу','pen','drawing'))}<div class="pagecontent stack">${head('Два рисунка. Равные условия.','Проверь, как форма меняет поведение башни — с одинаковым бюджетом на оборону.',tag('Испытание бесплатно','good'))}<div class="card row between"><label class="field-label grow">Сценарий<select><option>Смешанная волна</option><option>Быстрые цели</option><option>Бронированные цели</option></select></label><label class="field-label grow">Бюджет<select><option>300 штрихов</option><option>600 штрихов</option></select></label><div class="row"><span class="small">Ответный огонь</span><button class="switch on" role="switch" aria-checked="true" aria-label="Ответный огонь"></button></div>${B('Повторить испытание','play','','primary')}</div><div class="grid2">${[0,1].map(i=>`<div class="card stack"><div class="row between"><div><span class="small muted">${i?'Сравниваемый чертёж':'Текущий чертёж'}</span><h3>${i?'Страж · длинный ствол':'Страж'}</h3></div>${B('Заменить','refresh','album','small ghost')}</div><div class="trial-stage scene-grid">${svg(`${S('chassis.standard',100,120,60)}${S('weapon.gun',110,110,55,90)}${[0,1,2,3,4].map((n)=>S('enemy.'+(n%2?'runner':'doodle')+'.outlined.idle',300+n*35,85+(n%3)*32,33)).join('')}<path d="M140 115h180" stroke="#3158dc" stroke-width="2"/>`,'0 0 540 220')}</div><div class="row between"><span class="small muted">${i?'5 башен · 285 штр.':'5 башен · 255 штр.'}</span>${tag(i?'Прорвалось: 4':'Прорвалось: 6',i?'good':'')}</div></div>`).join('')}</div><div class="grid2"><div class="stack"><div class="row between"><h3>Результат испытания</h3>${tag('Демонстрация записи','blue')}</div><div class="trial-table">${[['Показатель','Страж','Длинный ствол'],['Поражено целей','18','20'],['Урон по целям','1 240','1 480'],['Урон замку','24','16'],['Башни потеряны','1','1']].map((r,i)=>r.map((v,j)=>`<div class="${i===0?'head':j===2?'best':''}">${v}</div>`).join('')).join('')}</div></div><div class="card soft stack"><h3>Запись боя</h3><div class="row">${IB('play','Воспроизвести запись')}<input type="range" min="0" max="100" value="64" aria-label="Позиция в записи" class="grow"><span class="small">0:24 / 0:38</span></div><p class="small">Сравнивай не только урон: цена постройки меняет число башен, которое помещается в бюджет.</p>${B('Подробные результаты','info','','secondary')}</div></div></div>${foot(B('К проверке','back','review','ghost'),B('Вернуться к рисунку','pen','drawing','primary'))}</div>`}
function stencils(){let names=['Прямой ствол','Узкий ствол','Широкий ствол','Раздвоенный силуэт','Перо','Ступенчатый'];return `<div class="screen">${titlebar('Заготовки рисунка','drawing',tag('Слой: ствол 1','blue'))}<div class="pagecontent"><div class="page-grid"><section class="stack">${head('Хорошее начало для своего рисунка','Вставь заготовку, затем меняй её форму обычными инструментами.')}<div class="row"><button class="chip selected" data-select="stencil-tab">Для ствола</button><button class="chip" data-select="stencil-tab">Для корпуса</button><button class="chip" data-select="stencil-tab">Декор</button></div><div class="grid3">${names.map((n,i)=>`<button class="card clickable ${i===0?'selected':''}" ${i>3?'data-go="purchase"':'data-select="stencil"'}><div class="artbox">${A('weapon.'+weaponIds[i])}</div><h3>${n}</h3><div class="row between" style="margin-top:14px">${tag(i>3?'Закрыта':'Доступна',i>3?'':'good')}${i>3?`<span class="currency small">${I('lock')} 60</span>`:''}</div></button>`).join('')}</div></section><aside class="sidebar"><div class="card soft stack"><h2>Прямой ствол</h2><div class="artbox" style="height:180px">${A('weapon.gun')}</div><p>Нейтральная форма, которую удобно удлинить, расширить или дополнить декором.</p>${note('Вставка заменит рисунок выбранного слоя. Другие слои сохранятся.')}<div class="push">${B('Вставить заготовку','check','drawing','primary wide')}</div></div><p class="small">Открытие за золото — навсегда. Применение открытой формы бесплатно.</p></aside></div></div>${foot(B('К рисунку','back','drawing','ghost'),'', 'Заготовки не фиксируют характеристики: результат зависит от твоих правок')}</div>`}
function special(type){let armor=type==='armor',fan=type==='fan';let title=armor?'Усиление корпуса':fan?'Направления веера':'Отпечаток мортиры';let subtitle=armor?'Защита там, откуда приходит удар.':fan?'Один залп — несколько направлений.':'Нарисуй форму будущего попадания.';let art=armor?`<circle cx="300" cy="230" r="160" fill="#3158dc05" stroke="#c1cfe8" stroke-dasharray="6 6"/><path d="M170 140A160 160 0 0 1 430 140" stroke="#3158dc" stroke-width="23" fill="none"/><path d="M430 140a160 160 0 0 1 0 180" stroke="#8fa7ef" stroke-width="15" fill="none"/><path d="M170 320a160 160 0 0 1 0-180" stroke="#bdcbef" stroke-width="9" fill="none"/>${S('chassis.standard',300,230,150)}<path d="M300 22v65m-12-15 12 15 12-15" stroke="#b63d56" stroke-width="3" fill="none"/><text x="315" y="45" fill="#9e3a4c" font-size="17">Пробный удар</text>`:fan?`${S('chassis.standard',300,345,85)}${S('weapon.fan',300,330,80)}${[-52,-26,0,26,52].map((a,i)=>{let x=300+Math.sin(a*Math.PI/180)*260,y=320-Math.cos(a*Math.PI/180)*260;return `<path d="M300 320 ${x} ${y}" stroke="#3158dc" stroke-width="2" stroke-dasharray="7 5"/><circle cx="${x}" cy="${y}" r="9" fill="white" stroke="#3158dc" stroke-width="2"/><text x="${x-6}" y="${y-19}" fill="#536e9a" font-size="15">${i+1}</text>`}).join('')}`:`<ellipse cx="300" cy="230" rx="190" ry="115" fill="#e7edff" stroke="#3158dc" stroke-width="3"/><path d="M90 230h420M300 90v280" stroke="#a2b6e9" stroke-dasharray="5 6"/>${[[200,195],[280,210],[350,250],[430,220],[490,330],[120,320]].map(([x,y],i)=>S('enemy.doodle.outlined.idle',x,y,35)).join('')}<circle cx="300" cy="230" r="7" fill="#3158dc"/>`;
let side=armor?`${row('Бюджет защиты','12 / 12')}${row('Спереди','6')}${row('Справа','4')}${row('Слева','2')}${row('Сзади','0')}<p class="small">Общий запас ограничен. Усиление одной стороны оставляет меньше защиты другим.</p>`:fan?`${row('Направления','5')}${row('Отклонения','−52° … +52°')}<p class="small">Перетяни точки, чтобы задать направления. Визуальный веер показывает распределение залпа.</p>${note('Широкий веер покрывает больше пространства, но меньше выстрелов сходятся на одной цели.')}`:`${row('Форма','Свободный контур')}${row('Площадь','1,6 → 2,2','blue')}${row('Цели в отпечатке','4 из 6')}<p class="small">Форма определяет область попадания. Это не изменение траектории снаряда.</p>`;
return `<div class="screen">${titlebar(title,'weapons',tag(armor?'Установлена броня':'Ствол 1','blue'))}<div class="pagecontent"><div class="page-grid"><section class="card stack">${head(subtitle,armor?'Распредели бюджет по сторонам и проверь корпус ударом.':fan?'Каждый луч заканчивается точкой, за которую можно изменить его направление.':'Сравни, как компактный, продольный и поперечный контуры накрывают цели.')}<div class="row">${B('Сбросить','refresh','','small secondary')}${B(armor?'Равномерно':fan?'Симметрично':'Эллипс',armor?'shield':fan?'mirror':'circle','','small secondary')}${B(armor?'Вперёд':fan?'Узкий веер':'Прямоугольник',armor?'arrow':fan?'target':'square','','small secondary')}</div><div class="special-canvas scene-grid">${svg(art,'0 0 600 460')}</div>${!armor&&!fan?`<div class="compare-strip">${['Компактный','Продольный','Поперечный'].map((s,i)=>`<button class="card ${i===2?'selected':''}" data-select="footprint">${svg(`<ellipse cx="60" cy="35" rx="${[25,12,48][i]}" ry="${[25,30,14][i]}" fill="#e7edff" stroke="#3158dc" stroke-width="2"/>`,'0 0 120 70')}<p>${s}</p></button>`).join('')}</div>`:`<div class="row between"><span class="small muted">${armor?'Направление отсчитывается от передней стороны башни.':'Лучи редактируются относительно направления стрельбы.'}</span>${B('Отменить','undo','','small ghost')}</div>`}</section><aside class="sidebar"><div class="card stack"><h2>${armor?'Бюджет защиты':fan?'Настройка залпа':'Форма попадания'}</h2>${side}<div class="rule"></div><h3>Проверить результат</h3>${B(armor?'Пробный удар':fan?'Пробный залп':'Пробный удар','target','','primary wide')}<p class="small muted">Испытание не расходует золото.</p></div>${note('Изменения относятся к выбранной детали. Другие стволы сохраняют свои настройки.')}</aside></div></div>${foot(B('К оружию','back','weapons','ghost'),B('Готово','check','weapons','primary'))}</div>`}
function dock(){return `<div class="battle-bottom"><div class="dock-section"><div class="dock-label">Чертежи</div><div class="dockgroup">${blueprints.map((b,i)=>`<button class="docktile ${i===0?'selected':''}" data-select="battle-tool" aria-label="${b[0]}, ${b[2]} штрихов"><kbd>${i+1}</kbd>${tower(b[3])}<small>${b[0]}</small><span>${b[2]}</span></button>`).join('')}</div></div><div class="dock-divider"></div><div class="dock-section"><div class="dock-label">Постройки</div><div class="dockgroup">${[['wall','Стена'],['spikes','Шипы'],['tar','Смола'],['repair','Ремонт']].map(([s,n],i)=>`<button class="docktile" data-select="battle-tool" aria-label="${n}"><kbd>${i+5}</kbd>${A('ui.tool.'+s)}<small>${n}</small></button>`).join('')}</div></div><div class="dock-divider"></div><div class="dock-section tools"><div class="dock-label">Инструменты</div><div class="dockgroup">${[['erase','Ластик'],['upgrade','Усилить'],['blotter','Промок.'],['paint','Окрасить']].map(([s,n])=>`<button class="docktile" data-select="battle-tool" aria-label="${n}">${A('ui.tool.'+s)}<small>${n}</small></button>`).join('')}</div></div><div class="dock-divider"></div><div class="materials">${['Карандаш','Ручка','Фломастер'].map((s,i)=>`<button class="chip ${i===0?'selected':''}" data-select="battle-material">${s}</button>`).join('')}</div><div class="inks">${[['#697c94','Без цвета'],['#bd3b50','Красные'],['#3158dc','Синие'],['#26765c','Зелёные']].map(([c,n],i)=>`<button class="inkchip" style="color:${c}" data-select="ink" title="${n}" aria-label="${n}">${I(i?'drop':'circle')}<span>${i?['',32,28,41][i]:'—'}</span></button>`).join('')}</div></div>`}
function battle(mode='battle'){let plan=mode==='planning',selected=mode==='tower';return `<div class="battle-screen"><header class="battle-top"><span class="battle-title">Первый рубеж</span><div class="resource">${I('pen')}<div><strong>${plan?'516':'184'}</strong><small class="muted"> штр.</small></div></div><div class="resource hp">${I('heart')}<div><strong>${plan?'250':'218'}</strong><small class="muted"> / 250</small></div></div><div class="wave-indicator"><strong>${plan?'Волна 1 / 8':'Волна 3 / 8'}</strong><small>${plan?'Готовь оборону':'Целей осталось: 17'}</small></div>${plan?B('Начать волну','play','battle','primary'):B('Пауза','pause','pause','secondary')}${B('×1','fast','','secondary')}${IB('settings','Настройки','settings')}</header><div class="battle-body"><aside class="well-rail">${[['#bd3b50','Красная'],['#3158dc','Синяя'],['#26765c','Зелёная']].map(([c,n],i)=>`<button class="well" data-act="feedback" title="${n} чернильница"><span style="color:${c}">${I('drop')}</span><strong>${[32,28,41][i]}</strong><small>${n}</small></button>`).join('')}<div class="small muted" style="text-align:center;font-size:.65rem">Запас<br>чернил</div></aside><section class="battlefield scene-grid" data-act="select-tower">${field(mode)}<div class="field-banner ${plan?'':'live'}">${I(plan?'pen':'flag')}${plan?'Расставь башни перед атакой':'Три направления атаки'}</div><div class="field-help">${keys('ЛКМ')} Построить / выбрать · ${keys('ПКМ')} Отмена</div><div class="field-controls">${IB('minus','Отдалить')}${IB('plus','Приблизить')}${IB('fit','Вся карта')}</div>${selected?'<div class="selection-mark"></div>':''}</section><aside class="battle-notes"><div class="card stack">${selected?`<div class="row between"><h3>Страж</h3>${tag('Ур. 1','blue')}</div><div class="artbox">${tower(0)}</div><div>${row('Прочность','72 / 87,6')}${row('Урон','12,6')}${row('Дальность','8,6')}</div>${B('Улучшить · 36','plus','','primary wide')}${B('Стереть','erase','','small ghost')}`:`<h3>${plan?'Первая волна':'Сейчас на странице'}</h3><div>${[['doodle','Каракули','Основная группа'],['runner','Бегуны','Быстрые цели'],['gnawer','Грызуны','Атакуют постройки']].map(([e,n,s])=>`<div class="enemy-row">${A('enemy.'+e+'.outlined.idle')}<div><strong class="small">${n}</strong><small class="muted">${s}</small></div></div>`).join('')}</div><p class="small">${plan?'Начни с перекрёстного огня у замка.':'Следи за проходами и запасом штрихов.'}</p>`}</div><div class="card soft stack secondary-note"><h3>${selected?'Общая подача':'Выбран: Страж'}</h3><p class="small">${selected?'Несколько стволов одной башни делят подачу. Форма влияет на характеристики каждого ствола.':'51 штрих · карандаш. Сначала выбери место, затем поставь башню.'}</p>${B('Показать радиусы','eye','','small ghost')}</div>${!plan?B('После волны →','','upgrades','small ghost'):''}</aside></div>${dock()}</div>`}
function overlay(body,wide=false){return `<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="Диалог">${body}</section></div>`}
function pause(){return battle()+overlay(`<div class="hero-icon">${I('pause')}</div><div class="center"><h1>Можно выдохнуть</h1><p>Бой приостановлен. Оборона подождёт.</p></div>${B('Продолжить','play','battle','primary wide')}<div class="grid2">${B('Настройки','settings','settings')}${B('Как играть','help','help')}</div><div class="rule"></div><div class="row between">${B('Начать заново','refresh','leave','ghost')}${B('Выйти в меню','exit','leave','ghost')}</div><p class="small muted center">Волна 3 / 8 · Первый рубеж</p>`)}
function upgrades(){return battle()+overlay(`<div class="center"><div class="kicker">Волна завершена</div><h1>Новый штрих к обороне</h1><p>Выбери одно усиление. Оно действует до конца этой миссии.</p></div><div class="grid3">${[['bolt','Быстрая подача','Темп стрельбы ×1,28','Больше выстрелов за то же время.'],['drop','Глубокие чернила','Урон +15% · HP +20%','Больше урона и прочнее оборона.'],['refresh','Бережный расход','+80 штрихов сразу','Награда за волну +25%. Возврат при стирании +12 п.п.']].map(([ic,n,s,d])=>`<article class="card upgrade-card"><div class="upgrade-icon">${I(ic)}</div><h2>${n}</h2><strong class="blue">${s}</strong><p>${d}</p>${B('Выбрать','check','planning','primary wide')}</article>`).join('')}</div><p class="small muted center">Бой приостановлен до выбора. На этом экране строительство недоступно.</p>`,true)}
function result(win=true){return `<div class="screen result-screen">${titlebar('Результат миссии','map',B('Альбом','book','album'))}<div class="result-hero"><div class="result-illustration">${svg(`${S(win?'object.castle':'object.castle.damaged',250,240,120)}${win?`<path d="M90 100v22m-11-11h22M410 160v22m-11-11h22M360 45v26m-13-13h26" stroke="#3158dc" stroke-width="3"/><path d="M125 350q130 55 260-5" fill="none" stroke="#3158dc" stroke-width="3"/>`:S('enemy.doodle.outlined.idle',420,350,45)}`,'0 0 500 480')}</div><section class="result-copy"><div class="kicker">${I(win?'trophy':'flag')} Первый рубеж</div><h1>${win?'Линия выдержала.':'Перерисуем план?'}</h1><p>${win?'Все восемь волн позади. Твоя оборона защитила страницу.':'Оборона продержалась пять волн. Попробуй прикрыть свободный подход и усилить башни у замка.'}</p><div class="result-metrics">${metric(win?'8 / 8':'5 / 8','волн отражено')}${metric(win?'146':'0','HP замка')}${metric(win?'+120':'+45','золота')}</div>${note('Золото и сохранённые чертежи остаются с тобой.','good')}<button class="btn small ghost" data-toggle="result-stats">${I('down')} Статистика миссии</button><div class="result-extra" id="result-stats" hidden>${row('Уничтожено целей',win?'284':'146')}${row('Вложено штрихов','1 240')}${row('Возвращено','128')}${row('Потеряно вложений','230')}${row('Максимум врагов','32')}${row('Нанесено урона','8 420')}${row('Построено / разрушено','24 / 6')}${row('Выбрано усилений','3')}</div><div class="row">${B(win?'К карте':'Попробовать снова',win?'map':'refresh',win?'map':'preparation','primary')}${B('В мастерскую','pen','foundation')}</div>${win?B('Повторить миссию','refresh','preparation','ghost'):B('К карте','map','map','ghost')}</section></div>${foot(B('В меню','back','home','ghost'),'',win?'Победа — повод попробовать другой рисунок':'Каждая попытка — новый чертёж обороны')}</div>`}
function settings(){let rr=(t,d,control)=>`<div class="setting-row"><div><h3>${t}</h3><p>${d}</p></div>${control}</div>`,sw=(n,on)=>`<button class="switch ${on?'on':''}" role="switch" aria-checked="${on}" aria-label="${n}"></button>`;return `<div class="screen">${titlebar('Настройки','home',B('Как играть','help','help'))}<div class="pagecontent"><div class="settings-layout"><nav class="settings-nav"><button class="btn selected" data-section="display">${I('eye')}Экран</button><button class="btn ghost" data-section="controls">${I('move')}Управление</button></nav><section class="stack"><div class="card" id="settings-display">${head('Удобно для тебя','Основные параметры отображения игры.')}${rr('Полный экран','Игра на всём экране.',sw('Полный экран',true))}${rr('Радиусы башен','Показывать зону стрельбы при выборе.',sw('Радиусы башен',true))}${rr('Масштаб интерфейса','Крупнее текст и элементы управления.',`<select aria-label="Масштаб интерфейса" style="width:140px" data-setting="scale"><option value="1">100%</option><option value="1.25">125%</option><option value="1.5">150%</option></select>`)}${rr('Меньше движения','Спокойные переходы и обратная связь.',sw('Меньше движения',false))}</div><div class="card" id="settings-controls"><h2>Управление</h2>${[['Строительство / выбор','ЛКМ'],['Отменить действие','ПКМ'],['Боевой чертёж','1 — 4'],['Пауза / назад','Esc']].map(([a,b])=>`<div class="shortcut-row"><span>${a}</span>${keys(b)}</div>`).join('')}<p class="small muted" style="margin-top:18px">Все основные действия доступны кнопками на экране.</p></div></section></div></div>${foot(B('Назад','back','home','ghost'),B('Готово','check','home','primary'),'Изменения применяются сразу')}</div>`}
function help(){return `<div class="screen">${titlebar('Как играть','home',B('Попробовать в мастерской','pen','foundation','primary'))}<div class="pagecontent stack">${head('Нарисуй. Испытай. Удержи.','Форма башни — часть тактики. Начни с простого и меняй один параметр за раз.')}<div class="grid3">${[['pen','1. Собери и нарисуй','Выбери основу и оружие. Площадь корпуса влияет на прочность, форма ствола — на его характеристики.','foundation'],['target','2. Испытай и сохрани','Попробуй выстрел, затем сравни чертежи на полигоне. Сохрани удачный вариант в альбом.','trial'],['castle','3. Защити страницу','Назначь четыре чертежа в набор. Строй за штрихи и переживи восемь волн.','preparation']].map(([ic,n,d,r])=>`<div class="card stack"><div class="upgrade-icon blue">${I(ic)}</div><h2>${n}</h2><p>${d}</p><div class="push">${B('Посмотреть','arrow',r,'ghost')}</div></div>`).join('')}</div><div class="grid2"><div class="card stack"><h2>Два разных ресурса</h2><div class="help-card">${I('pen')}<div><h3>Штрихи — здесь и сейчас</h3><p>Постройки и действия во время миссии расходуют её запас. Планируй оборону в пределах бюджета.</p></div></div><div class="help-card">${I('lock')}<div><h3>Золото — для коллекции</h3><p>Открывает детали и заготовки навсегда. Рисовать и испытывать конструкции можно бесплатно.</p></div></div></div><div class="card stack"><h2>Полезно помнить</h2><div class="help-card">${I('layers')}<div><h3>Одна башня — общая подача</h3><p>Несколько стволов делят ресурсы корпуса. Следи за общей нагрузкой.</p></div></div><div class="help-card">${I('drop')}<div><h3>Материал и цвет — разные настройки</h3><p>Карандаш, ручка и фломастер выбираются отдельно от красных, синих и зелёных чернил.</p></div></div></div></div></div>${foot(B('Назад','back','home','ghost'),B('Начать игру','arrow','map','primary'))}</div>`}
function purchase(){return stencils()+overlay(`<div class="modal-title"><h1>Открыть «Перо»?</h1>${B('','close','stencils','icon-only ghost')}</div><div class="row"><div class="artbox" style="width:160px;height:130px">${A('weapon.ricochet')}</div><div class="grow"><h3>Заготовка для ствола</h3><p>Станет доступна навсегда. После открытия форму можно вставлять бесплатно.</p></div></div><div class="card soft">${row('Открытие','60 золота')}${row('Сейчас','240')}${row('Останется','180','green')}</div><div class="modal-actions">${B('Отмена','','stencils')}${B('Открыть за 60','lock','stencils','primary')}</div><p class="small muted">Открытие не вставляет форму автоматически.</p>`)}
function saveError(){return review()+overlay(`<div class="modal-title"><h1>Не удалось сохранить</h1>${B('','close','review','icon-only ghost')}</div>${note('Не удалось записать чертёж в альбом. Твой рисунок остался в мастерской.','error')}<p>Повтори сохранение. Если ошибка останется, продолжай работу с текущим черновиком.</p><div class="modal-actions">${B('К черновику','back','drawing')}${B('Повторить сохранение','save','album','primary')}</div>`)}
function leave(){return battle()+overlay(`<div class="modal-title"><h1>Завершить этот бой?</h1>${B('','close','pause','icon-only ghost')}</div><p>Текущая расстановка и ход волн будут потеряны. Продолжить этот бой позже не получится.</p>${note('Сохранённые чертежи и заработанное золото останутся.')}<div class="modal-actions">${B('Остаться','back','pause','primary')}${B('Завершить и выйти','exit','home','danger')}</div>`)}
function system(){return `<div class="screen">${titlebar('Система интерфейса','home',tag('Чистый лист · v1','blue'))}<div class="pagecontent stack">${head('Один язык для всей игры','Тихая бумага, синие действия и рисунок как главный герой.')}<div class="colors">${[['#f5f7fc','Фон'],['#ffffff','Поверхность'],['#233953','Текст'],['#3158dc','Действие'],['#26765c','Успех'],['#bd3b50','Ошибка']].map(([c,n])=>`<div><div class="swatch" style="background:${c}"></div><strong class="small">${n}</strong><p class="small">${c}</p></div>`).join('')}</div><div class="token-grid"><div class="card stack"><h2>Типографика</h2><h1>Большая идея</h1><h2>Название страницы</h2><h3>Понятное действие</h3><p>Читаемый текст для параметров, описаний и подсказок. Рукописный шрифт — только для крупных заголовков.</p><p class="small">Notebook Hand / Segoe UI · табличные цифры</p></div><div class="card stack"><h2>Состояния действий</h2><div class="row">${B('Основное действие','arrow','home','primary')}${B('Вторичное','pen')}${B('Удалить','trash','','danger')}</div><div class="row"><button class="btn" disabled>Недоступно</button><button class="btn selected">Выбрано ${I('check')}</button>${tag('Готово','good')}${tag('Нужно действие','warn')}</div>${note('У каждого недоступного действия — понятная причина.')}${note('Ошибка названа, следующий шаг указан.','error')}</div><div class="card stack"><h2>Размеры и ритм</h2>${row('Шаг отступов','4 / 8 / 12 / 16 / 24 / 32')}${row('Основная кнопка','48 px')}${row('Компактная кнопка','40–44 px')}${row('Панель / кнопка','20 px / 12 px')}</div><div class="card stack"><h2>Масштабирование</h2><p>На широком экране растёт игровое поле. На ноутбуке уменьшаются поля и декоративные интервалы. В компактном окне шаги мастерской становятся горизонтальными.</p><p class="small">1280×720 · 1600×1000 · 1920×1080 · 2560×1080 · 1024×768</p><div class="row">${I('eye')}${I('pen')}${I('target')}${I('layers')}${I('shield')}${I('drop')}${I('map')}${I('book')}</div></div></div></div>${foot(B('К эскизам','back','home','ghost'),B('Карта экранов','map','flow','primary'))}</div>`}
function flow(){return `<div class="screen">${titlebar('Карта экранов','home',tag('10 страниц · 28 эскизов','blue'))}<div class="pagecontent stack">${head('От первой линии до последней волны','Основной маршрут и ответвления текущей версии игры. Нажми карточку, чтобы открыть экран.')}<div class="flow-grid">${[['home','play','01 · Главное меню','Старт → карта. Мастерская, настройки, помощь.'],['map','map','02 · Карта','Одна миссия → подготовка.'],['preparation','layers','03 · Подготовка','Четыре слота + материал → бой.'],['planning','castle','04 · Бой','Расстановка → волна → усиление → следующая волна.'],['foundation','pen','05 · Мастерская','Основа → оружие → рисунок → проверка.'],['album','book','Альбом / полигон','Сохранить → назначить. Испытать → исправить.'],['mortar','target','Особые настройки','Мортира, веер и направленная броня.'],['pause','pause','06 · Пауза','Продолжить, настройки, помощь, завершение.'],['upgrades','bolt','07 · Усиление','Одно из трёх → подготовка следующей волны.'],['victory','trophy','08 · Результат','Победа / поражение → карта или новая попытка.'],['settings','settings','09 · Настройки','Экран и управление → возврат.'],['help','help','10 · Помощь','Краткий цикл + ресурсы + контекстные подсказки.']].map(([r,i,n,p])=>`<button class="flow-node" data-go="${r}">${I(i)}<h3>${n}</h3><p>${p}</p><span class="flow-arrow">Открыть экран →</span></button>`).join('')}</div>${note('Состояния: пустой альбом · закрытая деталь · незаконченный рисунок · ошибка сохранения · выход из боя')}</div>${foot(B('К эскизам','back','home','ghost'),B('Компоненты','grid','system','primary'))}</div>`}
const routes={home,map,preparation,foundation,weapons,drawing,details:()=>drawing('details'),review,album,trial,stencils,mortar:()=>special('mortar'),fan:()=>special('fan'),armor:()=>special('armor'),planning:()=>battle('planning'),battle,tower:()=>battle('tower'),pause,upgrades,victory:()=>result(true),defeat:()=>result(false),settings,help,empty:()=>album(true),purchase,'save-error':saveError,invalid:()=>drawing('invalid'),leave,system,flow};
let previous='home';let returnTo='home';let toastTimer;
function navigate(id){if(routes[id])location.hash=id;}
function render(){let id=location.hash.slice(1)||'home';if(!routes[id])id='home';if(['settings','help'].includes(id)&&!['settings','help'].includes(previous))returnTo=previous;document.getElementById('app').innerHTML=routes[id]();document.body.dataset.screen=id;document.querySelectorAll('button[data-select]').forEach(b=>b.setAttribute('aria-pressed',b.classList.contains('selected')));document.title=id+' · Эскиз интерфейса';if(['settings','help'].includes(id)){document.querySelectorAll('.top-title [data-go],.pagefooter [data-go="home"]').forEach(b=>b.dataset.go=returnTo)}const modal=document.querySelector('.modal');if(modal){modal.setAttribute('aria-label',modal.querySelector('h1')?.textContent||'Диалог');document.querySelector('.screen,.battle-screen')?.setAttribute('inert','');modal.querySelector('button')?.focus()}previous=id;parent.postMessage({kind:'route',id},'*');}
function toast(t){let el=document.getElementById('toast');el.textContent=t;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3000)}
document.addEventListener('click',e=>{let toggle=e.target.closest('[data-toggle]');if(toggle){let panel=document.getElementById(toggle.dataset.toggle);panel.hidden=!panel.hidden;toggle.setAttribute('aria-expanded',!panel.hidden);return}let go=e.target.closest('[data-go]');if(go){navigate(go.dataset.go);return}let sel=e.target.closest('[data-select]');if(sel){document.querySelectorAll(`[data-select="${sel.dataset.select}"]`).forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false')});sel.classList.add('selected');sel.setAttribute('aria-pressed','true');if(sel.dataset.select==='blueprint')toast('Выбран чертёж: '+sel.dataset.name);return}let sw=e.target.closest('.switch');if(sw){sw.classList.toggle('on');sw.setAttribute('aria-checked',sw.classList.contains('on'));return}let sec=e.target.closest('[data-section]');if(sec){document.getElementById('settings-'+sec.dataset.section)?.scrollIntoView({behavior:'smooth'});return}let act=e.target.closest('[data-act]');if(!act)return;let a=act.dataset.act;if(routes[a])navigate(a);else if(a==='select-tower')navigate('tower');else if(a==='assign')toast('Чертёж назначен в выбранный слот — пример обратной связи');else toast('Демонстрация интерфейса. Расчёты и игровой ввод выполняются в Unity.');});
document.addEventListener('input',e=>{if(e.target.dataset.filter==='blueprints'){let q=e.target.value.toLocaleLowerCase('ru');document.querySelectorAll('[data-name]').forEach(b=>b.hidden=!b.dataset.name.toLocaleLowerCase('ru').includes(q))}});
document.addEventListener('change',e=>{if(e.target.dataset.setting==='scale')document.documentElement.style.setProperty('--text-scale',e.target.value)});
document.addEventListener('keydown',e=>{if(e.key==='Tab'&&document.querySelector('.modal')){const focusable=[...document.querySelectorAll('.modal button:not(:disabled),.modal input,.modal select')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}if(e.key==='Escape'){let id=document.body.dataset.screen;let back={pause:'battle',purchase:'stencils','save-error':'review',leave:'pause',battle:'pause',tower:'battle',settings:returnTo,help:returnTo};if(back[id])navigate(back[id])}});
window.addEventListener('message',e=>{if(e.source!==parent)return;if(e.data?.kind==='textscale')document.documentElement.style.setProperty('--text-scale',String(e.data.value))});
window.addEventListener('hashchange',render);render();
